// Aviso al equipo de que alguien ha reservado. Los datos salen de la CITA en Directus, así
// vale para cualquier origen (web, WhatsApp, webchat, voz). Lo que pase el que llama (la web
// manda lo del formulario) manda sobre lo leído: es lo que la persona acaba de escribir.
// El correo sale de la cuenta conectada a la credencial `Gmail`, con Reply-To a quien reservó.
const i = $('Reserva hecha').first().json;
const cfg = $('Config (editar por tenant)').first().json;
const destinos = String(cfg.aviso_reservas_email || '').split(',').map((s) => s.trim()).filter(Boolean);

const txt = (v) => (v === undefined || v === null ? '' : String(v).trim());
const cab = (v) => txt(v).replace(/[\r\n]+/g, ' '); // un salto en una cabecera inyecta otra
const correoValido = (v) => /^[^\s@<>,;"]+@[^\s@<>,;"]+\.[^\s@<>,;"]{2,}$/.test(v);
if (!destinos.some(correoValido)) {
  throw new Error('AVISO_RESERVAS_EMAIL no tiene ningún correo válido: ' + destinos.join(', '));
}

// La cita. Si no se puede leer, el aviso sale igual con lo que haya y lo dice: avisar de una
// reserva con datos a medias es mejor que no avisar.
const r = $('HTTP · Cita').first().json ?? {};
const st = r.statusCode ?? 0;
const a = (st >= 200 && st < 300 && r.body && r.body.data) || null;
const c = (a && a.contact_id) || {};
const tels = Array.isArray(c.phones) ? c.phones : [];
const telFicha = txt(((tels.find((p) => p.is_primary) || tels[0]) || {}).phone_number);

const nombre = txt(i.nombre) || [txt(c.first_name), txt(c.last_name)].filter(Boolean).join(' ');
const email = (txt(i.email) || txt(c.email)).toLowerCase();
const telefono = txt(i.telefono) ? '+' + txt(i.telefono).replace(/^\+/, '') : telFicha;
const empresa = txt(i.empresa) || txt(c.company);
const servicio = txt(i.servicio) || txt(a && a.service_id && a.service_id.name);
const inicio = txt(i.inicio) || txt(a && a.start_at);
let minutos = txt(i.duracion_minutos);
if (!minutos && a && a.start_at && a.end_at) {
  minutos = String(Math.round((Date.parse(a.end_at) - Date.parse(a.start_at)) / 60000));
}

const t = DateTime.fromISO(inicio, { setZone: true }).setZone('Europe/Madrid').setLocale('es');
const cuando = t.isValid ? t.toFormat("cccc d 'de' LLLL 'a las' HH:mm") : inicio;

const ORIGENES = {
  web: 'desde la web',
  lucia_whatsapp: 'con Lucía por WhatsApp',
  lucia_webchat: 'con Lucía en el chat de la web',
  lucia_voz: 'con Lucía por teléfono',
};
const origen = ORIGENES[txt(i.origen)] || 'con Lucía';

// El panel es `panel.<dominio>` y los webhooks `lucia.<dominio>` (los subdominios de un
// tenant son fijos). Si la dirección no tiene esa forma, el aviso va sin enlace.
const publico = txt(cfg.webhook_publico);
const panel = /^https:\/\/lucia\./.test(publico) ? publico.replace('https://lucia.', 'https://panel.') : '';
const enlace = panel && txt(i.cita_id) ? `${panel}/admin/content/appointments/${txt(i.cita_id)}` : '';

// La web manda su mensaje aparte; de Lucía, lo que haya en las notas de la cita.
const mensaje = txt(i.mensaje);
const notas = !mensaje ? txt(a && a.notes) : '';

const lineas = [
  `${nombre || 'Alguien'} ha reservado ${origen}.`,
  '',
  `Servicio: ${servicio}`,
  `Cuándo: ${cuando}${minutos ? ` (${minutos} min)` : ''}`,
  '',
  `Nombre: ${nombre || '(sin nombre)'}`,
  email ? `Correo: ${email}` : null,
  telefono ? `Teléfono: ${telefono}` : null,
  empresa ? `Empresa: ${empresa}` : null,
  ...(mensaje ? ['', 'Qué quiere resolver:', mensaje] : []),
  ...(notas ? ['', 'Notas de la cita:', notas] : []),
  ...(enlace ? ['', `La cita en el panel: ${enlace}`] : []),
  ...(!a ? ['', `(No se pudo leer la cita en Directus: ${st || 'sin respuesta'}. Faltan datos.)`] : []),
  '',
  txt(i.origen) === 'web'
    ? 'La invitación con el enlace de Meet le llega por separado; si Google no pudiera mandarla, aparecerá una tarea en el panel.'
    : 'Lucía ya le ha confirmado la cita en la conversación.',
  correoValido(email) ? 'Respondiendo a este correo le escribes a quien ha reservado.' : null,
].filter((l) => l !== null);

const b64 = (s) => Buffer.from(s, 'utf8').toString('base64');
const palabra = (s) => `=?UTF-8?B?${b64(s)}?=`; // RFC 2047: tildes en el asunto
const asunto = `Nueva reserva: ${cab(nombre) || 'sin nombre'} · ${cab(cuando)}`;
const cabeceras = [
  `To: ${destinos.filter(correoValido).join(', ')}`,
  `Subject: ${palabra(asunto)}`,
  correoValido(email) ? `Reply-To: ${email}` : null,
  'MIME-Version: 1.0',
  'Content-Type: text/plain; charset=UTF-8',
  'Content-Transfer-Encoding: base64',
].filter(Boolean);
const cuerpo = b64(lineas.join('\r\n')).match(/.{1,76}/g).join('\r\n');
const mime = cabeceras.join('\r\n') + '\r\n\r\n' + cuerpo;
// La API de Gmail quiere el mensaje entero en base64url.
const raw = Buffer.from(mime, 'utf8').toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
return [{ json: { raw, para: destinos, asunto, cita_leida: !!a } }];

// Un aviso que no sale tiene que verse: la ejecución acaba en error, no en verde.
const r = $json ?? {};
const st = r.statusCode ?? 0;
if (st >= 200 && st < 300) {
  const c = $('Code · Correo').first().json;
  return [{ json: { ok: true, id: (r.body && r.body.id) || null, para: c.para, asunto: c.asunto, cita_leida: c.cita_leida } }];
}
const b = r.body || {};
throw new Error(`Gmail rechazó el aviso (${st}): ${(b.error && b.error.message) || JSON.stringify(b).slice(0, 300)}`);
